mapper.delete:
DELETE FROM expdb.exp_role_permission_rel
WHERE role_id = #{roleId}
  AND perm_id IN (
      SELECT perm_id
      FROM expdb.exp_permission
      WHERE perm_code IN

          #{permCode}

  )

mapper.select:
SELECT p.perm_id AS permId, p.perm_code AS permCode, p.perm_name AS permName, p.perm_type AS permType, p.module_code AS moduleCode, p.group_code AS groupCode, p.perm_value AS permValue, p.status AS status, p.sort_no AS sortNo, p.remark AS remark, rp.role_id AS roleId, rp.grant_type AS grantType FROM expdb.exp_permission p INNER JOIN expdb.exp_role_permission_rel rp ON p.perm_id = rp.perm_id WHERE rp.role_id IN
#{roleId}
AND p.status = 'ENABLED' ORDER BY p.sort_no
